DLLEXPORT int tjDecompress2(tjhandle handle, const unsigned char *jpegBuf, /* <=== tjDecompress2 */ 
                            unsigned long jpegSize, unsigned char *dstBuf,
                            int width, int pitch, int height, int pixelFormat,
                            int flags)
{
